package com.nthexperience.desktop;
import android.app.Activity;
import android.content.ClipData;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import java.util.*;

/** Ten overview, named desktops and moving built-in windows without detaching their contents. */
final class TenTaskView {
 final Activity activity;final FrameLayout host;final TenDesktops desktops;final Runnable refresh;FrameLayout overlay;final List<Bitmap> images=new ArrayList<>();int safeLeft,safeRight,safeTop;
 TenTaskView(Activity a,FrameLayout host,TenDesktops desktops,Runnable refresh){activity=a;this.host=host;this.desktops=desktops;this.refresh=refresh;}
 void safeInsets(int l,int r,int t){safeLeft=l;safeRight=r;safeTop=t;if(overlay!=null&&(overlay.getPaddingLeft()!=l||overlay.getPaddingTop()!=t||overlay.getPaddingRight()!=r||overlay.getPaddingBottom()!=0))overlay.setPadding(l,t,r,0);}
 boolean dismiss(){if(overlay==null)return false;host.removeView(overlay);overlay=null;for(Bitmap b:images)b.recycle();images.clear();return true;}
 private int dp(int n){return Aero.dp(activity,n);}private TextView darkButton(String text,Runnable action){TextView v=TenStyle.command(activity,text,action);v.setTextColor(Color.WHITE);return v;}
 void show(List<DesktopWindow> windows,List<String> external,java.util.function.Function<String,String> label,java.util.function.Consumer<String> open){dismiss();desktops.sync();overlay=new FrameLayout(activity);overlay.setElevation(dp(40));overlay.setPadding(safeLeft,safeTop,safeRight,0);overlay.setContentDescription("Task View");overlay.setBackgroundColor(0xee171717);overlay.setClickable(true);LinearLayout body=Aero.column(activity);body.setPadding(dp(12),dp(8),dp(12),dp(8));overlay.addView(body,new FrameLayout.LayoutParams(-1,-1));
  LinearLayout header=new LinearLayout(activity);TextView title=Aero.text(activity,"Task View",20,Color.WHITE);header.addView(title,new LinearLayout.LayoutParams(0,dp(40),1));header.addView(darkButton("Close",this::dismiss));body.addView(header);HorizontalScrollView strip=new HorizontalScrollView(activity);strip.setHorizontalScrollBarEnabled(false);LinearLayout row=new LinearLayout(activity);strip.addView(row);body.addView(strip,new LinearLayout.LayoutParams(-1,dp(82)));
  for(TenDesktops.Desk desk:desktops.list()){LinearLayout tile=Aero.column(activity);tile.setPadding(dp(8),dp(7),dp(8),dp(7));tile.setGravity(Gravity.CENTER_VERTICAL);tile.setBackground(Aero.panel(activity,desk.id.equals(desktops.current())?0xff315b78:0xff303030,0xff303030,0,desk.id.equals(desktops.current())?TenStyle.accent(activity):0xff555555));TextView name=Aero.text(activity,desk.name,13,Color.WHITE);name.setMaxLines(1);tile.addView(name);long count=desk.windows.values().stream().filter(w->w.getParent()!=null).count();tile.addView(Aero.text(activity,count+" open windows",10,0xffcccccc));tile.setContentDescription("Switch desktop "+desk.name);tile.setFocusable(true);tile.setOnClickListener(v->{desktops.select(desk.id);refresh.run();});ContextMenus.bind(tile,(x,y)->desktopMenu(tile,desk));tile.setOnDragListener((v,e)->{if(!(e.getLocalState() instanceof DesktopWindow))return false;if(e.getAction()==DragEvent.ACTION_DROP){if(!desktops.move((DesktopWindow)e.getLocalState(),desk.id))Toast.makeText(activity,"That tool is already open on this desktop.",Toast.LENGTH_SHORT).show();refresh.run();}return true;});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(155),dp(68));p.rightMargin=dp(10);row.addView(tile,p);}
  TextView create=darkButton("+ New desktop",()->{String id=desktops.create();if(id!=null){desktops.select(id);refresh.run();}});create.setContentDescription("New desktop");create.setEnabled(desktops.list().size()<TenDesktops.LIMIT);row.addView(create,new LinearLayout.LayoutParams(dp(140),dp(68)));
  TextView info=Aero.text(activity,desktops.name()+" · Open windows",12,0xffdddddd);body.addView(info,new LinearLayout.LayoutParams(-1,dp(32)));ScrollView scroll=new ScrollView(activity);GridLayout cards=new GridLayout(activity);int cols=Math.max(1,Math.min(4,(host.getWidth()-safeLeft-safeRight)/dp(220)));cards.setColumnCount(cols);scroll.addView(cards);body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  for(DesktopWindow window:windows){if(window.getParent()==null)continue;LinearLayout card=Aero.column(activity);card.setBackgroundColor(0xff333333);LinearLayout bar=new LinearLayout(activity);TextView caption=Aero.text(activity,window.caption(),12,Color.WHITE);caption.setPadding(dp(8),0,0,0);caption.setSingleLine();bar.addView(caption,new LinearLayout.LayoutParams(0,dp(36),1));TextView close=darkButton("×",()->{window.closeWindow();refresh.run();});close.setContentDescription("Close "+window.caption());bar.addView(close,new LinearLayout.LayoutParams(dp(40),-1));card.addView(bar);
   View preview;if(WindowPreviews.allowed(window)&&window.getWidth()>0&&window.getHeight()>0){try{float scale=Math.min(440f/window.getWidth(),240f/window.getHeight());Bitmap bitmap=Bitmap.createBitmap(Math.max(1,(int)(window.getWidth()*scale)),Math.max(1,(int)(window.getHeight()*scale)),Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(bitmap);canvas.scale(scale,scale);window.drawPreview(canvas);images.add(bitmap);ImageView image=new ImageView(activity);image.setImageBitmap(bitmap);image.setScaleType(ImageView.ScaleType.FIT_CENTER);preview=image;}catch(RuntimeException|OutOfMemoryError e){preview=Aero.text(activity,"Preview unavailable",12,Color.WHITE);}}else preview=Aero.text(activity,"Private preview hidden",12,Color.WHITE);card.addView(preview,new LinearLayout.LayoutParams(-1,dp(120)));card.setContentDescription("Switch to "+window.caption());card.setFocusable(true);card.setOnClickListener(v->{dismiss();window.restore();});ContextMenus.desktopIcon(card,(x,y)->windowMenu(card,window),()->card.startDragAndDrop(ClipData.newPlainText("window",window.caption()),new View.DragShadowBuilder(card),window,0));cards.addView(card,cell(cards,cols));
  }
  for(String id:external){TextView app=darkButton("Android app: "+label.apply(id),()->{dismiss();open.accept(id);});cards.addView(app,cell(cards,cols));}
  if(cards.getChildCount()==0){TextView empty=Aero.text(activity,"Open a tool or app to see it here.",14,Color.WHITE);cards.addView(empty);}
  host.addView(overlay,new FrameLayout.LayoutParams(-1,-1));overlay.bringToFront();overlay.setFocusableInTouchMode(true);overlay.requestFocus();overlay.setOnKeyListener((v,key,e)->{if(key==KeyEvent.KEYCODE_ESCAPE&&e.getAction()==KeyEvent.ACTION_UP){dismiss();return true;}return false;});
 }
 private void desktopMenu(View anchor,TenDesktops.Desk desk){PopupMenu menu=new PopupMenu(activity,anchor);menu.getMenu().add("Rename desktop").setOnMenuItemClickListener(item->{EditText name=new EditText(activity);name.setSingleLine();name.setText(desk.name);name.setContentDescription("Desktop name");android.app.AlertDialog dialog=Aero.dialog(activity).setTitle("Rename desktop").setView(name).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{if(desktops.rename(desk.id,name.getText().toString())){dialog.dismiss();refresh.run();}else name.setError("Use 1–60 characters");}));dialog.show();return true;});menu.getMenu().add("Close desktop").setEnabled(desktops.list().size()>1).setOnMenuItemClickListener(item->{if(!desktops.remove(desk.id))Toast.makeText(activity,"Move or close duplicated tools before closing this desktop.",Toast.LENGTH_LONG).show();refresh.run();return true;});menu.show();}
 private void windowMenu(View anchor,DesktopWindow window){PopupMenu menu=new PopupMenu(activity,anchor);SubMenu move=menu.getMenu().addSubMenu("Move to desktop");for(TenDesktops.Desk desk:desktops.list())if(!desk.id.equals(desktops.current()))move.add(desk.name).setEnabled(desktops.canMove(window,desk.id)).setOnMenuItemClickListener(item->{desktops.move(window,desk.id);refresh.run();return true;});menu.getMenu().add("Close window").setOnMenuItemClickListener(item->{window.closeWindow();refresh.run();return true;});menu.show();}
 private GridLayout.LayoutParams cell(GridLayout grid,int cols){int n=grid.getChildCount();GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(n/cols),GridLayout.spec(n%cols));p.width=Math.max(1,(host.getWidth()-safeLeft-safeRight-dp(24))/cols-dp(10));p.height=dp(156);p.setMargins(dp(5),0,dp(5),dp(12));return p;}
}
